import React, { useCallback } from 'react';
import type { ComponentProps, FC, ReactNode } from 'react';

import { useNestedMenu } from './use_nested_menu';
import { SecondaryMenu } from '../secondary_menu';

export interface PrimaryMenuItemProps
  extends Omit<ComponentProps<typeof SecondaryMenu.Item>, 'children' | 'isHighlighted'> {
  children: ReactNode;
  hasSubmenu?: boolean;
  isCurrent?: boolean;
  isHighlighted?: boolean;
  onClick?: () => void;
}

export const PrimaryMenuItem: FC<PrimaryMenuItemProps> = ({
  children,
  hasSubmenu = false,
  id,
  isCurrent,
  isHighlighted = false,
  onClick,
  ...props
}) => {
  const { goToPanel } = useNestedMenu();

  const handleClick = useCallback(() => {
    if (hasSubmenu) {
      goToPanel(id, id);
    } else {
      onClick?.();
    }
  }, [hasSubmenu, id, goToPanel, onClick]);

  return (
    <SecondaryMenu.Item
      id={id}
      isHighlighted={isHighlighted}
      isCurrent={isCurrent}
      onClick={handleClick}
      hasSubmenu={hasSubmenu}
      {...props}
    >
      {children}
    </SecondaryMenu.Item>
  );
};
